    BEFORE UPDATE ON recognition_of_stroke_in_the_emergency_room_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE recognition_of_stroke_in_the_emergency_room_grade_flag IS
